target.css:
:root {
  --surface: #fffdf8;
  --ink: #25352f;
  --muted: #718078;
  --line: #d8e1d9;
  --accent: #e56645;
  --accent-soft: #fff0e9;
  --mint: #dff3e5;
  --mint-ink: #28714d;
  --dark: #28483d;
}

.slot-card {
  width: 480px;
  box-sizing: border-box;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--surface);
  color: var(--ink);
}

.slot-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: 16px 18px 14px;
  border-bottom: 1px solid var(--line);
}

.eyebrow {
  margin: 0 0 5px;
  color: var(--accent);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

h2 {
  margin: 0;
  font-size: 21px;
  line-height: 1.1;
  letter-spacing: -0.03em;
}

.status {
  padding: 5px 9px;
  border-radius: 999px;
  background: var(--mint);
  color: var(--mint-ink);
  font-size: 12px;
  font-weight: 800;
}

.machine-row {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 14px 18px;
}

.machine-icon {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  border-radius: 10px;
  background: var(--accent-soft);
  color: var(--accent);
  font-size: 20px;
}

.machine-meta {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.machine-meta strong {
  font-size: 14px;
  line-height: 1.2;
}

.machine-meta span {
  color: var(--muted);
  font-size: 12px;
}

.details {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  margin: 0 18px;
  border: 1px solid var(--line);
  border-radius: 12px;
}

.detail {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 10px 12px;
  border-right: 1px solid var(--line);
}

.detail:last-child {
  border-right: 0;
}

.detail-label {
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.07em;
}

.detail-value {
  font-size: 12px;
  line-height: 1.2;
}

.slot-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 14px;
  padding: 12px 18px;
  background: var(--accent-soft);
}

.member {
  display: flex;
  align-items: center;
  gap: 8px;
}

.avatar {
  display: grid;
  width: 29px;
  height: 29px;
  place-items: center;
  border-radius: 50%;
  background: var(--dark);
  color: var(--surface);
  font-size: 10px;
  font-weight: 800;
}

.member span:last-child {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.member strong {
  font-size: 12px;
}

.member small {
  color: var(--muted);
  font-size: 10px;
}

button {
  border: 0;
  border-radius: 8px;
  padding: 8px 11px;
  background: var(--accent);
  color: var(--surface);
  font-size: 12px;
  font-weight: 800;
}

